data.preprocessor.yaml:
# SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
# SPDX-License-Identifier: Apache-2.0

openapi: 3.0.3
info: {title: Dynamo canonical preprocessor facade, version: "1.0"}
paths:
  /prepare:
    post:
      operationId: prepare
      x-grpc: {service: dynamo.components.v1.Preprocessor, method: Prepare}
      x-grpc-json-bytes: true
      x-batch:
        intoField: items
        responseField: items
        operationId: prepareBatch
      requestBody:
        required: true
        content:
          application/json:
            schema:
              type: object
              required: [item_id, openai_request_json]
              properties:
                item_id: {type: string}
                openai_request_json: {type: object}
                preserve_omitted_max_tokens: {type: boolean}
                lora_name: {type: string}
                deadline_unix_ms: {type: integer}
                packed_tokens_only: {type: boolean}
      responses:
        "200":
          content:
            application/json:
              schema: &prepared
                type: object
                properties:
                  item_id: {type: string}
                  normalized_openai_request_json: {type: object}
                  backend_request_json: {type: object}
                  selector_request_json: {type: object}
                  token_ids: {type: array, items: {type: integer}}
                  token_ids_le: {type: string}
                  annotations: {type: object}
                  prompt_injected_reasoning: {type: boolean}
                  uses_tool_call_structural_tag: {type: boolean}
                  prompt_tokens: {type: integer}
                  image_tokens: {type: integer}
                  image_count: {type: integer}
                  video_count: {type: integer}
                  audio_count: {type: integer}
                  error: {type: object}
  /prepare_batch:
    post:
      operationId: prepareBatch
      x-grpc: {service: dynamo.components.v1.Preprocessor, method: PrepareBatch}
      x-grpc-json-bytes: true
      requestBody:
        required: true
        content:
          application/json:
            schema:
              type: object
              required: [items]
              properties:
                items: {type: array, items: {type: object}}
      responses:
        "200":
          content:
            application/json:
              schema:
                type: object
                required: [items]
                properties:
                  items: {type: array, items: *prepared}

